const input = $input.first().json;
const raw = input.body;

const payload = typeof raw === 'string'
  ? JSON.parse(raw)
  : raw;

const event = payload?.events?.[0];

if (
  event?.type !== 'message' ||
  event?.message?.type !== 'text' ||
  !event?.replyToken
) {
  return [];
}

const question = event.message.text.trim();
const q = question.replace(/\s+/g, '').toLowerCase();

let answer = '';

const menu = `ร้านคั่วชามเปลมีเมนูดังนี้ค่ะ
1) คั่วไก่ 80 บาท
2) คั่วทะเล (พิเศษ) 130 บาท
3) โจ๊กหมู (ธรรมดา) 60 บาท
4) ปาท่องโก๋ 8 บาท
5) โจ๊กหมูใส่ไข่ (ธรรมดา) 65 บาท`;

// 1. ตรวจเมนูที่มีข้อมูลก่อน
if (q.includes('คั่วทะเล')) {
  answer = 'คั่วทะเล (พิเศษ) ราคา 130 บาทค่ะ';

} else if (q.includes('คั่วไก่')) {
  answer = 'คั่วไก่ ราคา 80 บาทค่ะ';

} else if (q.includes('ปาท่องโก๋')) {
  answer = 'ปาท่องโก๋ ราคา 8 บาทค่ะ';

} else if (q.includes('โจ๊ก') && q.includes('ไข่')) {
  answer = 'โจ๊กหมูใส่ไข่ (ธรรมดา) ราคา 65 บาทค่ะ';

} else if (q.includes('โจ๊ก')) {
  answer = 'มีค่ะ โจ๊กหมูธรรมดา 60 บาท และโจ๊กหมูใส่ไข่ธรรมดา 65 บาทค่ะ';

// 2. ตรวจการขอดูเมนูทั้งหมด
} else if (
  /^(ขอ)?(ดู|ขอดู)?เมนู(อาหาร)?(ทั้งหมด|หน่อย|มีอะไรบ้าง)?(ครับ|ค่ะ)?$/.test(q) ||
  q.includes('รายการอาหาร') ||
  q.includes('อาหารมีอะไรบ้าง')
) {
  answer = menu;

// 3. ตรวจคำทักทาย
} else if (/สวัสดี|หวัดดี|hello|^hi$/.test(q)) {
  answer = 'สวัสดีค่ะ ยินดีต้อนรับสู่ร้านคั่วชามเปล 😊 พิมพ์ "ขอเมนูอาหาร" เพื่อดูเมนูได้เลยค่ะ';

// 4. ไม่มีข้อมูล
} else {
  answer = 'ขออภัยค่ะ ยังไม่มีข้อมูลเมนูนี้ในรายการที่ใช้สำหรับการสอบ สามารถสอบถามเมนูอื่นได้ค่ะ';
}

return [{
  json: {
    replyToken: event.replyToken,
    answer
  }
}];
